#include "club/Club.h"
#include <bit>
namespace fl {
namespace {
struct W {std::vector<std::uint8_t>b;void n(std::uint64_t x,int c=4){for(int i=0;i<c;++i)b.push_back(static_cast<std::uint8_t>(x>>(8*i)));}void s(const std::string& v){n(v.size(),2);b.insert(b.end(),v.begin(),v.end());}void cards(const std::vector<std::uint16_t>& v){n(v.size(),2);for(auto d:v)n(d,2);}};
struct R {std::span<const std::uint8_t>b;std::size_t at=0;bool ok=true;std::uint64_t n(int c=4){if(b.size()-at<static_cast<std::size_t>(c)){ok=false;return 0;}std::uint64_t x=0;for(int i=0;i<c;++i)x|=static_cast<std::uint64_t>(b[at++])<<(8*i);return x;}std::string s(std::size_t max){const auto count=n(2);if(count>max||count>b.size()-at){ok=false;return{};}std::string v(b.begin()+static_cast<std::ptrdiff_t>(at),b.begin()+static_cast<std::ptrdiff_t>(at+count));at+=count;return v;}std::vector<std::uint16_t> cards(std::size_t max){const auto count=n(2);if(count>max){ok=false;return{};}std::vector<std::uint16_t>v;for(unsigned i=0;i<count&&ok;++i){const auto d=n(2);if(d>=302)ok=false;v.push_back(static_cast<std::uint16_t>(d));}return v;}bool flag(){const auto x=n(1);if(x>1)ok=false;return x==1;}bool done(){return ok&&at==b.size();}};
}
std::vector<std::uint8_t> encodeClubCommand(const ClubCommand& c){W w;w.n(static_cast<unsigned>(c.op),1);w.s(c.request);w.s(c.name);w.n(std::bit_cast<std::uint32_t>(c.value));w.cards(c.cards);w.n(c.face.size());w.b.insert(w.b.end(),c.face.begin(),c.face.end());return w.b;}
std::optional<ClubCommand> decodeClubCommand(std::span<const std::uint8_t> b){R r{b};ClubCommand c;const auto op=r.n(1);if(op<1||op>10)return{};c.op=static_cast<ClubOp>(op);c.request=r.s(32);c.name=r.s(32);c.value=std::bit_cast<int>(static_cast<std::uint32_t>(r.n()));c.cards=r.cards(120);const auto count=r.n();if(count>facePixels||count!=b.size()-r.at)return{};c.face.assign(b.begin()+static_cast<std::ptrdiff_t>(r.at),b.end());r.at=b.size();if(c.request.size()!=32)return{};return r.done()?std::optional{c}:std::nullopt;}
std::vector<std::uint8_t> encodeClubView(const ClubView& v){W w;w.n(static_cast<std::uint64_t>(v.profile.cents),8);w.s(v.profile.selected);w.n(v.profile.owned.size(),2);for(auto n:v.profile.owned)w.n(n);w.n(v.profile.decks.size(),1);for(const auto& d:v.profile.decks){w.s(d.name);w.cards(d.cards);}for(int i=0;i<2;++i){w.n(v.match.ready[i],1);w.n(v.match.reset[i],1);w.n(v.match.life[i]+1000,2);w.n(v.match.votes[i]+1,1);}w.n(v.match.active,1);w.n(v.match.winner+1,1);w.s(v.status);w.cards(v.opened);return w.b;}
std::optional<ClubView> decodeClubView(std::span<const std::uint8_t> b){R r{b};ClubView v;const auto money=r.n(8);if(money>1000000000)return{};v.profile.cents=static_cast<std::int64_t>(money);v.profile.selected=r.s(32);const auto owned=r.n(2);if(owned!=302)return{};for(unsigned i=0;i<owned;++i)v.profile.owned.push_back(static_cast<std::uint32_t>(r.n()));const auto decks=r.n(1);if(decks>16)return{};for(unsigned i=0;i<decks&&r.ok;++i){SavedDeck d;d.name=r.s(32);d.cards=r.cards(120);v.profile.decks.push_back(std::move(d));}for(int i=0;i<2;++i){v.match.ready[i]=r.flag();v.match.reset[i]=r.flag();v.match.life[i]=static_cast<int>(r.n(2))-1000;v.match.votes[i]=static_cast<int>(r.n(1))-1;if(v.match.life[i]<-999||v.match.life[i]>999||v.match.votes[i]>1)r.ok=false;}v.match.active=r.flag();v.match.winner=static_cast<int>(r.n(1))-1;if(v.match.winner>1)r.ok=false;v.status=r.s(160);v.opened=r.cards(15);return r.done()?std::optional{v}:std::nullopt;}
}
